type UpsertRepoSubscriptionParams struct {
	UserID uuid.UUID
	RepoID uuid.UUID
	Level  string
}

func (q *Queries) UpsertRepoSubscription(ctx context.Context, arg UpsertRepoSubscriptionParams) (RepoSubscription, error) {
	row := q.db.QueryRow(ctx, upsertRepoSubscription, arg.UserID, arg.RepoID, arg.Level)
	var i RepoSubscription
	err := row.Scan(
		&i.UserID,
		&i.RepoID,
		&i.Level,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertThreadSubscription = `-- name: UpsertThreadSubscription :one
INSERT INTO thread_subscriptions (user_id, repo_id, subject_key, subscribed)
VALUES ($1, $2, $3, $4)
ON CONFLICT (user_id, subject_key) DO UPDATE SET subscribed = EXCLUDED.subscribed, created_at = now()
RETURNING user_id, repo_id, subject_key, subscribed, created_at
`

type UpsertThreadSubscriptionParams struct {
	UserID     uuid.UUID
	RepoID     uuid.UUID
	SubjectKey string
	Subscribed bool
}

func (q *Queries) UpsertThreadSubscription(ctx context.Context, arg UpsertThreadSubscriptionParams) (ThreadSubscription, error) {
	row := q.db.QueryRow(ctx, upsertThreadSubscription,
		arg.UserID,
		arg.RepoID,
		arg.SubjectKey,
		arg.Subscribed,
	)
	var i ThreadSubscription
	err := row.Scan(
		&i.UserID,
		&i.RepoID,
		&i.SubjectKey,
		&i.Subscribed,
		&i.CreatedAt,
	)
	return i, err
}
